assert chunk_set is not None
yield tracer.event("request", clock, request_data)

def budget_state(state: StateStore, settings: Settings) -> BudgetState:
    spent = state.month_spend()
    cap = settings.budget_monthly_usd
    if spent >= cap:
        tier: Tier = "stopped"
    elif spent >= cap * settings.budget_degrade_at:
        tier = "degraded"
    else:
        tier = "normal"
    return BudgetState(spent, cap, tier, cap * settings.budget_degrade_at)

